import itertools
import json

def build_graph(edges):
    graph = {}
    for a, b in edges:
        graph.setdefault(a, set()).add(b)
        graph.setdefault(b, set()).add(a)
    return graph

def compute_itinerary(cities, stays, edges, total_days, must_be_in, friend_window):
    graph = build_graph(edges)
    assert set(cities) == set(stays.keys())
    assert "Nice" in cities
    others = [c for c in cities if c != "Nice"]
    target_nice_days = stays["Nice"]

    def is_adjacent_path(seq):
        for i in range(len(seq) - 1):
            if seq[i+1] not in graph.get(seq[i], set()):
                return False
        return True

    for perm in itertools.permutations(others):
        seq = list(perm) + ["Nice"]
        # Check direct flights adjacency across the whole sequence
        if not is_adjacent_path(seq):
            continue

        # Nice must include both must_be_in days; with our overlapping rule, this forces Nice to be last and span exact days
        # We already placed Nice last; compute day ranges
        day_ranges = {}
        start_day = 1
        for city in seq:
            end_day = start_day + stays[city] - 1
            day_ranges[city] = (start_day, end_day)
            start_day = end_day  # overlap on transition day

        # Compute presence sets and validate totals
        presence = {city: set(range(s, e+1)) for city, (s, e) in day_ranges.items()}
        union_days = set().union(*presence.values())
        # Validate total unique calendar days
        if len(union_days) != total_days or min(union_days) != 1 or max(union_days) != total_days:
            continue

        # Validate per-city stay counts
        per_city_ok = all(len(presence[city]) == stays[city] for city in cities)
        if not per_city_ok:
            continue

        # Validate conference days in Nice
        nice_days = presence["Nice"]
        if not all(day in nice_days for day in must_be_in.get("Nice", [])):
            continue

        # Validate friend window in Oslo (at least one day overlap)
        fw_start, fw_end = friend_window.get("Oslo", (None, None))
        if fw_start is not None and fw_end is not None:
            if len(presence["Oslo"].intersection(set(range(fw_start, fw_end+1)))) == 0:
                continue

        # All constraints satisfied; construct itinerary output
        itinerary = []
        for city in seq:
            s, e = day_ranges[city]
            itinerary.append({
                "day_range": f"Day {s}-{e}",
                "place": city
            })
        return itinerary

    # If no itinerary found, return empty list
    return []

def main():
    # Input variables (constraints)
    total_days = 16
    stays = {
        "Mykonos": 4,
        "Nice": 3,
        "London": 2,
        "Copenhagen": 3,
        "Oslo": 5,
        "Tallinn": 4
    }
    cities = list(stays.keys())
    edges = [
        ("London", "Copenhagen"),
        ("Copenhagen", "Tallinn"),
        ("Tallinn", "Oslo"),
        ("Mykonos", "London"),
        ("Oslo", "Nice"),
        ("London", "Nice"),
        ("Mykonos", "Nice"),
        ("London", "Oslo"),
        ("Copenhagen", "Nice"),
        ("Copenhagen", "Oslo"),
    ]
    must_be_in = {
        "Nice": [14, 16]  # must attend conference in Nice on day 14 and day 16
    }
    friend_window = {
        "Oslo": (10, 14)  # meet friend in Oslo between day 10 and day 14 inclusive
    }

    itinerary = compute_itinerary(cities, stays, edges, total_days, must_be_in, friend_window)
    output = {"itinerary": itinerary}
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
